"""Paired offline refinement of candidates generated by the official planner."""

import csv
import json
import time
from pathlib import Path

import numpy as np
import torch

from score_function.evaluation.common import (
    create_output,
    load_evaluation,
    select_frame_trace,
    synchronize,
)
from score_function.evaluation.metrics import MetricAccumulator, finite_scalar, trajectory_metrics
from score_function.evaluation.reporting import format_metric
from score_function.evaluation.visualization import plot_trajectory
from score_function.utils.train_utils import (
    atomic_write,
    file_hash,
    read_json,
    resolve_path,
)


@torch.no_grad()
def evaluate_planner(config, checkpoint, split="val", output=None, max_samples=None):
    """Paired offline original-planner candidates; no closed-loop simulator is run.

    One deterministic original candidate is used for the before/after pair. Raw
    NPZ inputs are required; contexts cached for training alone cannot generate a
    baseline prediction. Refinement traces are streamed rather than retained.
    """
    from score_function.model.refinement import refine_ego
    from score_function.utils.dataset import build_data_loader, device_batch
    from score_function.utils.feature_dataset import read_feature_batch
    from score_function.utils.normalizer import denormalize_ego_future, normalize_ego_future
    from score_function.utils.planner_utils import (
        ego_normalizer_metadata,
        load_frozen_planner,
        planner_identity,
    )
    from score_function.utils.sampling import predict_candidates

    directory = create_output(config, output, f"planner_offline_{split}")
    dataset = None
    started = time.perf_counter()
    try:
        device, model, state, dataset, indices = load_evaluation(
            config, checkpoint, split, max_samples
        )
        if planner_identity(config) != state["planner"]:
            raise ValueError("Planner-output evaluation requires checkpoint's exact frozen planner")
        planner, planner_args = load_frozen_planner(config, device)
        normalizer = dataset.metadata["ego_normalizer"]
        if normalizer != ego_normalizer_metadata(planner_args):
            raise ValueError("Planner/cached ego normalization differs")
        sigma = float(state["config"]["training"]["sigma"])
        settings, refinement = config.get("evaluation", {}), config["refinement"]
        gamma, steps = float(refinement["gamma"]), int(refinement["steps"])
        disabled = gamma == 0 or steps == 0
        selected_records = [dataset.records[index] for index in indices]
        if any("feature" not in record for record in selected_records):
            manifest = read_json(resolve_path(config, "manifest"))
            source = {record["token"]: record for record in manifest}
            selected_records = [
                {**source[record["token"]], **record} for record in selected_records
            ]
        by_token = {record["token"]: record for record in selected_records}
        for record in selected_records:
            path = Path(record["feature"])
            if not path.is_file() or (
                record.get("feature_sha256") and file_hash(path) != record["feature_sha256"]
            ):
                raise ValueError(f"Missing/changed planner input feature: {path}")
        baseline, recovered, diagnostics = (
            MetricAccumulator(),
            MetricAccumulator(),
            MetricAccumulator(),
        )
        planner_seconds, refinement_seconds, completed = 0.0, 0.0, 0
        plotted, plot_limit = 0, int(settings.get("visualize_samples", 8))
        loader_settings = {
            **config["training"],
            "microbatch_size": int(settings.get("batch_size", 64)),
        }
        metric_names = ("mse_normalized", "ade_m", "fde_m", "heading_mae_rad")
        fields = ["token", "recording", "start_time_us", "split", "sigma", "gamma", "steps"]
        fields += [f"{prefix}_{key}" for prefix in ("before", "after") for key in metric_names]
        fields += [f"improved_{key}" for key in metric_names]
        fields += [
            "displacement_ade_m",
            "displacement_fde_m",
            "displacement_l2_normalized",
            "initial_score_l2",
            "initial_score_d1",
            "initial_score_d2",
        ]
        with (
            (directory / "per_sample.csv").open("w", encoding="utf-8", newline="") as csv_stream,
            (directory / "per_sample.jsonl").open("w", encoding="utf-8") as json_stream,
            (directory / "refinement_traces.jsonl").open("w", encoding="utf-8") as trace_stream,
        ):
            writer = csv.DictWriter(csv_stream, fieldnames=fields)
            writer.writeheader()
            for cpu_batch in build_data_loader(dataset, loader_settings, indices=indices):
                batch = device_batch(cpu_batch, device)
                records = [by_token[token] for token in batch["tokens"]]
                inputs, target = read_feature_batch(records, planner_args, device)
                torch.testing.assert_close(target, batch["target"], rtol=0, atol=0)
                synchronize(device)
                tick = time.perf_counter()
                encoding, output = predict_candidates(
                    planner,
                    planner_args,
                    inputs,
                    [record["start_time_us"] for record in records],
                    config["reference_seed"],
                )
                route = planner.decoder.decoder.dit.route_encoder(inputs["route_lanes"])
                synchronize(device)
                planner_seconds += time.perf_counter() - tick
                physical_initial = output["prediction"][:, 0]
                initial = normalize_ego_future(physical_initial, planner_args.state_normalizer)
                final, trace = refine_ego(
                    model,
                    initial,
                    encoding["encoding"],
                    route,
                    planner_args.state_normalizer,
                    sigma,
                    gamma,
                    steps,
                    heading_projection=refinement["heading_projection"],
                    record_trace=True,
                )
                refinement_seconds += sum(trace["step_seconds"])
                # Preserve exact physical predictions when refinement is disabled.
                physical_final = (
                    physical_initial
                    if disabled
                    else denormalize_ego_future(final, planner_args.state_normalizer)
                )
                if disabled and not torch.equal(physical_initial, physical_final):
                    raise AssertionError("Disabled refinement changed physical output")
                before = trajectory_metrics(initial, target, normalizer)
                after = trajectory_metrics(final, target, normalizer)
                baseline.add(before)
                improvements = {
                    f"improved_{name}": (after[name] < before[name])
                    .float()
                    .masked_fill(
                        ~torch.isfinite(after[name]) | ~torch.isfinite(before[name]), float("nan")
                    )
                    for name in metric_names
                }
                recovered.add({**after, **improvements})
                displacement = (physical_final[..., :2] - physical_initial[..., :2]).norm(dim=-1)
                extras = {
                    "displacement_ade_m": displacement.mean(dim=-1),
                    "displacement_fde_m": displacement[:, -1],
                    "displacement_l2_normalized": (final - initial).flatten(1).norm(dim=-1),
                }
                first_score = (
                    torch.as_tensor(trace["scores"][0], device=device)
                    if trace["scores"]
                    else torch.zeros_like(initial)
                )
                extras.update(
                    {
                        "initial_score_l2": first_score.flatten(1).norm(dim=-1),
                        "initial_score_d1": torch.diff(first_score, dim=1)
                        .norm(dim=-1)
                        .mean(dim=-1),
                        "initial_score_d2": torch.diff(first_score, n=2, dim=1)
                        .norm(dim=-1)
                        .mean(dim=-1),
                    }
                )
                if disabled:
                    # No score was evaluated; zero would misleadingly claim a zero field.
                    for name in ("initial_score_l2", "initial_score_d1", "initial_score_d2"):
                        extras[name] = torch.full_like(extras[name], float("nan"))
                diagnostics.add(extras)
                arrays = {
                    **{
                        f"before_{key}": value.cpu().tolist()
                        for key, value in before.items()
                        if key in metric_names
                    },
                    **{
                        f"after_{key}": value.cpu().tolist()
                        for key, value in after.items()
                        if key in metric_names
                    },
                    **{
                        key: value.cpu().tolist()
                        for key, value in {**improvements, **extras}.items()
                    },
                }
                for index, record in enumerate(records):
                    token = record["token"]
                    row = {key: record[key] for key in ("token", "recording", "start_time_us")}
                    row.update(split=split, sigma=sigma, gamma=gamma, steps=steps)
                    row.update({key: finite_scalar(value[index]) for key, value in arrays.items()})
                    writer.writerow(row)
                    json_stream.write(json.dumps(row, allow_nan=False) + "\n")
                    sample_trace = select_frame_trace(trace, index)
                    trace_stream.write(
                        json.dumps(
                            {
                                "token": token,
                                "recording": record["recording"],
                                "start_time_us": record["start_time_us"],
                                "baseline_ego_physical": physical_initial[index].cpu().tolist(),
                                "refined_ego_physical": physical_final[index].cpu().tolist(),
                                "nuplan_score": None,
                                "nuplan_evaluation": "not run; offline only",
                                "trace": sample_trace,
                            },
                            allow_nan=False,
                        )
                        + "\n"
                    )
                    if plotted < plot_limit:
                        with np.load(record["feature"], allow_pickle=False) as raw:
                            map_data = {
                                key: raw[key] for key in ("lanes", "route_lanes") if key in raw
                            }
                        plot_trajectory(
                            directory / f"trajectory_{plotted:03d}.png",
                            target[index],
                            initial[index],
                            final[index],
                            gamma * sigma**2 * first_score[index],
                            normalizer,
                            f"{token}: planner offline K={steps}, gamma={gamma}",
                            map_data,
                            sample_trace["trajectories"][1:-1],
                        )
                        plotted += 1
                completed += len(records)
                atomic_write(
                    directory / "status.json",
                    {
                        "state": "running",
                        "completed_samples": completed,
                        "total_samples": len(indices),
                    },
                )
        summary = {
            "schema_version": 1,
            "kind": "paired_planner_offline",
            "split": split,
            "samples": completed,
            "available_samples": len(dataset),
            "checkpoint": str(Path(checkpoint).resolve()),
            "checkpoint_sha256": file_hash(checkpoint),
            "cache_sha256": dataset.sha256,
            "sigma": sigma,
            "gamma": gamma,
            "steps": steps,
            "heading_projection": refinement["heading_projection"],
            "disabled": disabled,
            "reference_seed": config["reference_seed"],
            "baseline": baseline.result(),
            "refined": recovered.result(),
            "diagnostics": diagnostics.result(),
            "timing": {
                "planner_seconds": planner_seconds,
                "branch_update_seconds": refinement_seconds,
                "planner_seconds_per_frame": planner_seconds / completed,
                "branch_update_seconds_per_frame": refinement_seconds / completed,
                "note": "Synchronized, batched amortized time; includes updates, excludes trace serialization. Not online single-scene latency.",
            },
            "numerical_failures": 0,
            "elapsed_seconds": time.perf_counter() - started,
            "interpretation": [
                "Same original candidate/seed for before and after; no extra inference noise.",
                "Expert imitation errors are offline diagnostics, not nuPlan planning scores.",
                "Fixed K is an iteration budget, not a density-peak or convergence certificate.",
                "Predicted neighbors are never modified or used as score-branch conditioning.",
            ],
        }
        atomic_write(directory / "summary.json", summary)
        lines = [
            "# Paired planner-output offline refinement",
            "",
            f"{completed} `{split}` frames; sigma={sigma}, gamma={gamma}, K={steps}; "
            f"heading projection={refinement['heading_projection']}.",
            "",
            "| Metric | Original planner | Refined | Improved fraction |",
            "|---|---:|---:|---:|",
        ]
        for name in metric_names:
            lines.append(
                f"| {name} | {format_metric(summary['baseline'][name]['mean'])} | "
                f"{format_metric(summary['refined'][name]['mean'])} | "
                f"{format_metric(summary['refined']['improved_' + name]['mean'])} |"
            )
        lines += [
            "",
            f"Mean XY displacement: {format_metric(summary['diagnostics']['displacement_ade_m']['mean'])} m.",
            f"Amortized branch/update time: {refinement_seconds / completed:.6g} s/frame.",
            "",
            *[f"- {note}" for note in summary["interpretation"]],
            "",
        ]
        (directory / "report.md").write_text("\n".join(lines), encoding="utf-8")
        atomic_write(directory / "status.json", {"state": "complete", "samples": completed})
        return summary
    except Exception as error:
        atomic_write(
            directory / "status.json",
            {
                "state": "failed",
                "error": f"{type(error).__name__}: {error}",
                "numerical_failure": isinstance(error, FloatingPointError),
            },
        )
        raise
    finally:
        if dataset is not None:
            dataset.close()
